}

// Next skips the rest of the current entry and returns the header of the next one, or io.EOF.
func (rd *Reader) Next() (*Header, error) {
	if !rd.started {
		rd.started = true
		magic := make([]byte, len(globalHeader))
		if _, err := io.ReadFull(rd.r, magic); err != nil {
			return nil, err
		}
		if string(magic) != globalHeader {
			return nil, ErrInvalidHeader
		}
	}

	if skip := rd.nb + rd.pad; skip > 0 {
		rd.nb, rd.pad = 0, 0
		if _, err := io.CopyN(io.Discard, rd.r, skip); err != nil {
			return nil, err
		}
	}

	buf := make([]byte, headerSize)
	if _, err := io.ReadFull(rd.r, buf); err != nil {
		return nil, err
	}
	if string(buf[58:]) != headerMagic {
		return nil, ErrInvalidHeader
	}

	size, err := strconv.ParseInt(string(bytes.TrimRight(buf[48:58], " ")), 10, 64)
	if err != nil || size < 0 {
		return nil, fmt.Errorf("%w: invalid size", ErrInvalidHeader)
	}
	mode, _ := strconv.ParseInt(string(bytes.TrimRight(buf[40:48], " ")), 8, 64)

	rd.nb = size
	rd.pad = size % 2
	return &Header{
		Name: string(bytes.TrimRight(buf[:16], " ")),
		Mode: mode,
		Size: size,
	}, nil
}

// Read reads from the current entry.
func (rd *Reader) Read(b []byte) (int, error) {
	if rd.nb <= 0 {
		return 0, io.EOF
	}
	if int64(len(b)) > rd.nb {
		b = b[:rd.nb]
	}
	n, err := rd.r.Read(b)
	rd.nb -= int64(n)
	return n, err
}

type Writer struct {
	w   io.Writer
	nb  int64
	pad int64
}

func NewWriter(w io.Writer) *Writer {
	return &Writer{w: w}
}

func (w *Writer) WriteGlobalHeader() error {
	_, err := io.WriteString(w.w, globalHeader)
	return err
}

func (w *Writer) WriteHeader(hdr *Header) error {
	if w.nb > 0 {
		return errors.New("ar: previous entry not fully written")
	}
	if w.pad > 0 {
		if _, err := w.w.Write([]byte{'\n'}); err != nil {
			return err
		}
		w.pad = 0
	}
	if len(hdr.Name) > 16 {
		return errors.New("ar: name too long")
	}
	// name, mtime, uid, gid, mode, size, magic
	line := fmt.Sprintf("%-16s%-12d%-6d%-6d%-8o%-10d%s", hdr.Name, 0, 0, 0, hdr.Mode, hdr.Size, headerMagic)
	if _, err := io.WriteString(w.w, line); err != nil {
		return err
	}
	w.nb = hdr.Size
	w.pad = hdr.Size % 2
	return nil
}

func (w *Writer) Write(b []byte) (int, error) {
	if int64(len(b)) > w.nb {
		return 0, errors.New("ar: write too long")
	}
	n, err := w.w.Write(b)
	w.nb -= int64(n)
	return n, err
}
