package ar

import (
	"bytes"
	"io"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestReaderWriter(t *testing.T) {
	var buf bytes.Buffer
	w := NewWriter(&buf)
	require.NoError(t, w.WriteGlobalHeader())
	for name, content := range map[string]string{"odd": "abc", "even": "abcd"} {
		require.NoError(t, w.WriteHeader(&Header{Name: name, Mode: 0o600, Size: int64(len(content))}))
		_, err := w.Write([]byte(content))
		require.NoError(t, err)
	}

	r := NewReader(&buf)
	seen := 0
	for {
		hd, err := r.Next()
		if err == io.EOF {
			break
		}
		require.NoError(t, err)
		data, err := io.ReadAll(r)
		require.NoError(t, err)
		assert.Len(t, data, int(hd.Size))
		seen++
	}
	assert.Equal(t, 2, seen)
}

func TestReaderNegativeSize(t *testing.T) {
	data := "!<arch>\n" + "x" + strings.Repeat(" ", 15) + strings.Repeat(" ", 12+6+6+8-0) + "-5        " + "`\n"
	_, err := NewReader(strings.NewReader(data)).Next()
	assert.ErrorIs(t, err, ErrInvalidHeader)
}
